INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/bete-de-lombre#capacite:bond', 'bestiaire/bete-de-lombre', 1, NULL, NULL, 'Bond', 'bond', 'Cette créature est capable de faire un bond équivalent à sa vitesse x2 en échange de 3IC.', NULL, 'bestiaire', 'Invocation › Marionette de lombre › G135:R144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/bete-de-lombre#capacite:folle-de-guerre', 'bestiaire/bete-de-lombre', 2, NULL, NULL, 'Folle de guerre', 'folle-de-guerre', 'Cette créature doit avancer vers l’ennemi, elle ne peut pas attendre et est immunisée contre toutes formes de peur.', NULL, 'bestiaire', 'Invocation › Marionette de lombre › G135:R144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/bete-de-lombre#capacite:vraiment-sournois', 'bestiaire/bete-de-lombre', 3, NULL, NULL, 'Vraiment sournois', 'vraiment-sournois', 'Quand l''adversaire n''est pas attentif au personnage, permet d''infliger un bonus de 4d4 dégâts en plus des dégâts de l''arme.', NULL, 'bestiaire', 'Invocation › Marionette de lombre › G135:R144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/carcalanche#capacite:craquellement:npm5', 'bestiaire/carcalanche', 3, 5, NULL, 'Craquellement', 'craquellement', 'Les armes qui le frappent directement et qui font 91 ou plus à leur jet perdent un cran de solidité.', NULL, 'bestiaire', 'Invocation › Animation des morts › G251:R260');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/carcalanche#capacite:fragilite-tranchante:npm3', 'bestiaire/carcalanche', 2, 3, NULL, 'Fragilité tranchante', 'fragilite-tranchante', 'Chaque fois qu’il subit une attaque physique, des éclats de glace sèche sont projetés autour de lui (2d6 dégâts dans une zone de 3 cases autour de lui).', NULL, 'bestiaire', 'Invocation › Animation des morts › G251:R260');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/carcalanche#capacite:souffle-elementaire', 'bestiaire/carcalanche', 1, NULL, NULL, 'Souffle élémentaire', 'souffle-elementaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquences pour ne pas prendre l''altération d''état)', NULL, 'bestiaire', 'Invocation › Animation des morts › G251:R260');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/charcabe#capacite:chargement:npm3', 'bestiaire/charcabe', 2, 3, NULL, 'Chargement', 'chargement', 'Permet de charger un sort d''attaque lvl1 ou lvl2 le premier tour et de l''utiliser en même temps que l''attaque de contact le tour suivant.', NULL, 'bestiaire', 'Invocation › Animation des morts › G193:R202');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/charcabe#capacite:lanceur-de-sorts', 'bestiaire/charcabe', 1, NULL, NULL, 'Lanceur de sorts', 'lanceur-de-sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Boule de feu, Braise magique.', NULL, 'bestiaire', 'Invocation › Animation des morts › G193:R202');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/charcabe#capacite:surchauffe:npm5', 'bestiaire/charcabe', 3, 5, NULL, 'Surchauffe', 'surchauffe', 'Permet de consommer le triple du coût du sort pour augmenter ses dégâts de 2d.', NULL, 'bestiaire', 'Invocation › Animation des morts › G193:R202');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/crieur-osseux#capacite:lanceur-de-sorts', 'bestiaire/crieur-osseux', 1, NULL, NULL, 'Lanceur de sorts', 'lanceur-de-sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Lame d''air, Propulsion.', NULL, 'bestiaire', 'Invocation › Animation des morts › W309:AH318');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/crieur-osseux#capacite:sort-supplementaire:npm5', 'bestiaire/crieur-osseux', 3, 5, NULL, 'Sort supplémentaire', 'sort-supplementaire', 'Cette créature obtient de nouveaux sorts en plus des autres : Vibration.', NULL, 'bestiaire', 'Invocation › Animation des morts › W309:AH318');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/crieur-osseux#capacite:terrain-favorable:npm3', 'bestiaire/crieur-osseux', 2, 3, NULL, 'Terrain favorable', 'terrain-favorable', 'Si jamais la météo est "Vent violent" ou "Tempête de sable", ses dégâts augmentent de +8 et son arme a le double de sa portée.', NULL, 'bestiaire', 'Invocation › Animation des morts › W309:AH318');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/double-sombre#capacite:sournois', 'bestiaire/double-sombre', 1, NULL, NULL, 'Sournois', 'sournois', 'Quand l''adversaire n''est pas attentif au personnage, permet d''infliger un bonus de 2d4 dégâts en plus des dégâts de l''arme.', NULL, 'bestiaire', 'Invocation › Marionette de lombre › G77:R86');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/embrase#capacite:attaque-brulante', 'bestiaire/embrase', 1, NULL, NULL, 'Attaque brûlante', 'attaque-brulante', 'L''attaque de cette créature est capable d''infliger une brûlure, oblige un jet de vigueur à la cible pour éviter "brûlure 1".', NULL, 'bestiaire', 'Invocation › Animation des morts › W193:AH202');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/embrase#capacite:deflagration:npm5', 'bestiaire/embrase', 3, 5, NULL, 'Déflagration', 'deflagration', 'Sacrifie la valeur de AP et AM pour les ajoutés comme modificateur aux dégâts pendant 3 tours.', NULL, 'bestiaire', 'Invocation › Animation des morts › W193:AH202');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/embrase#capacite:duelliste:npm3', 'bestiaire/embrase', 2, 3, NULL, 'Duelliste', 'duelliste', 'Si cette créature en affronte une autre seul à seul = +3 dégâts, +5% au jet de défense.', NULL, 'bestiaire', 'Invocation › Animation des morts › W193:AH202');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/executeur-lunaire#capacite:vraiment-sournois', 'bestiaire/executeur-lunaire', 1, NULL, NULL, 'Vraiment sournois', 'vraiment-sournois', 'Quand l''adversaire n''est pas attentif au personnage, permet d''infliger un bonus de 4d4 dégâts en plus des dégâts de l''arme.', NULL, 'bestiaire', 'Invocation › Marionette de lombre › G106:R115');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/fantome#capacite:en-t:npm5', 'bestiaire/fantome', 3, 5, NULL, 'En T', 'en-t', 'Lors de la mort de la créature, elle est capable de foncer sur un adversaire aléatoire et réduire de moitié son AM et lui mettre un malus de 20% à son prochain jet.', NULL, 'bestiaire', 'Invocation › Animation des morts › G135:R144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/fantome#capacite:immateriel', 'bestiaire/fantome', 1, NULL, NULL, 'Immatériel', 'immateriel', 'Cette créature est naturellement immunisée aux dégâts physiques (armes) , seules la magie, une arme spectrale ou une arme sous l’effet d’un sort “fer” peuvent la toucher. En plus de ça, son arme naturelle passe à travers les AP.', NULL, 'bestiaire', 'Invocation › Animation des morts › G135:R144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/fantome#capacite:renfermement:npm3', 'bestiaire/fantome', 2, 3, NULL, 'Renfermement', 'renfermement', 'Cette créature est capable de renfermé ses blessures au début de son tour. (Regagne toute sa santé)', NULL, 'bestiaire', 'Invocation › Animation des morts › G135:R144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/fulgurame#capacite:corps-electrique:npm5', 'bestiaire/fulgurame', 3, 5, NULL, 'Corps électrique', 'corps-electrique', 'Chaque attaque qu''un assaillant prodigue lui oblige de faire un de vigueur pour ne pas subir "Paralysie 1".', NULL, 'bestiaire', 'Invocation › Animation des morts › W338:AH347');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/fulgurame#capacite:lame-foudroyante', 'bestiaire/fulgurame', 1, NULL, NULL, 'Lame foudroyante', 'lame-foudroyante', '(IC) En échange de 5 chakra, la prochaine attaque physique au contact libère une foudre qui inflige 1d8 dégâts qui va ignorer l’AM et l’AP de la cible.', NULL, 'bestiaire', 'Invocation › Animation des morts › W338:AH347');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/fulgurame#capacite:reflexe-eclair:npm3', 'bestiaire/fulgurame', 2, 3, NULL, 'Réfléxe éclair', 'reflexe-eclair', '(IC) En échange de 5 chakra, augmente son prochain jet de défense de 10%.', NULL, 'bestiaire', 'Invocation › Animation des morts › W338:AH347');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-darcane#capacite:coup-alternatif:npm5', 'bestiaire/golem-darcane', 3, 5, NULL, 'Coup alternatif', 'coup-alternatif', 'Permet de choisir si l''attaque va prendre en compte l''armure physique ou bien l''armure magique de la cible.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G77:R86');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-darcane#capacite:immateriel', 'bestiaire/golem-darcane', 1, NULL, NULL, 'Immatériel', 'immateriel', 'Cette créature est naturellement immunisée aux dégâts physiques (armes) , seules la magie, une arme spectrale ou une arme sous l’effet d’un sort “fer” peuvent la toucher.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G77:R86');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-darcane#capacite:rune-immediate:npm3', 'bestiaire/golem-darcane', 2, 3, NULL, 'Rune immédiate', 'rune-immediate', 'Cette créature obtient une résistance à l’élément du dernier sort subi et cela plusieurs fois dans un tour (une résistance à la fois).', NULL, 'bestiaire', 'Invocation › Appel aux golems › G77:R86');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-boue#capacite:camouflage:npm5', 'bestiaire/golem-de-boue', 3, 5, NULL, 'Camouflage', 'camouflage', 'Cette créature inflige toujours des dégâts discrets tant qu''elle est dans le bon décor (eau).', NULL, 'bestiaire', 'Invocation › Appel aux golems › G251:R260');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-boue#capacite:frappe-confuse:npm3', 'bestiaire/golem-de-boue', 2, 3, NULL, 'Frappe confuse', 'frappe-confuse', 'L’arme de cette créature possède 30% de chance d’obliger un jet de fermeté à l’adversaire pour ne pas qu’il prenne “confusion 1”.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G251:R260');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-boue#capacite:gluant', 'bestiaire/golem-de-boue', 1, NULL, NULL, 'Gluant', 'gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G251:R260');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-chair#capacite:forme-changeante', 'bestiaire/golem-de-chair', 1, NULL, NULL, 'Forme changeante', 'forme-changeante', 'Cette créature à tout les début de tour (juste après l''initiative et avant tout le monde) change aléatoirement de forme et ainsi les bonus qu''elle possède, il y a 8 formes :
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-cristal#capacite:attaque-dissipante:npm5', 'bestiaire/golem-de-cristal', 3, 5, NULL, 'Attaque dissipante', 'attaque-dissipante', 'Tous les 2 tours, l’attaque de cette créature inflige l’effet du sort “dissipation” de la magie du vide.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G164:R173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-cristal#capacite:attaque-immaterielle:npm3', 'bestiaire/golem-de-cristal', 2, 3, NULL, 'Attaque immatérielle', 'attaque-immaterielle', 'Les armes de cette créature ignorent les AP données par les armures.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G164:R173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-cristal#capacite:sournois-invisible', 'bestiaire/golem-de-cristal', 1, NULL, NULL, 'Sournois invisible', 'sournois-invisible', 'Cette créature est invisible à l''œil nu et inflige également 2d4 dégâts en bonus comme attaque sournoise.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G164:R173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-foudre#capacite:anti-brumeux:npm3', 'bestiaire/golem-de-foudre', 2, 3, NULL, 'Anti Brumeux', 'anti-brumeux', 'Cette créature inflige un bonus de 10 dégâts contre les créature lié à la Brume Noir et peut protéger ses alliés à 4 cases de lui des effets négatifs de cette dernière.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G367:R376');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-foudre#capacite:distributeur-de-foudre:npm5', 'bestiaire/golem-de-foudre', 3, 5, NULL, 'Distributeur de foudre', 'distributeur-de-foudre', 'Chaque attaque de l’élément foudre va se distribuer à la cible la plus proche de la première (maximum 3 PO) et infliger la moitié des dégâts et ainsi de suite …', NULL, 'bestiaire', 'Invocation › Appel aux golems › G367:R376');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-foudre#capacite:plaque-miroir', 'bestiaire/golem-de-foudre', 1, NULL, NULL, 'Plaque miroir', 'plaque-miroir', 'Possède une plaque miroir qui peut absorber un sort niveau 3 maximum, cette plaque réapparaît tous les 3 tours.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G367:R376');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-glace#capacite:meteo-favorable', 'bestiaire/golem-de-glace', 1, NULL, NULL, 'Météo favorable', 'meteo-favorable', 'Tant que cette créature est dans une météo qui avantage sa magie, il gagne 10 aux dégâts qu’il inflige.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G280:R289');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-glace#capacite:neige-permanente:npm3', 'bestiaire/golem-de-glace', 2, 3, NULL, 'Neige permanente', 'neige-permanente', 'Invoque la météo “neige” en entrant sur le terrain et fait perdurer tant que personne ne la change.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G280:R289');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-glace#capacite:repression:npm5', 'bestiaire/golem-de-glace', 3, 5, NULL, 'Répression', 'repression', 'La météo invoquée par cette créature ne peut être annulée ou remplacée.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G280:R289');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-lumiere#capacite:anti-mal:npm5', 'bestiaire/golem-de-lumiere', 3, 5, NULL, 'Anti-mal', 'anti-mal', 'Inflige un bonus de +8 dégâts contre les créatures mauvaises.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G396:R405');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-lumiere#capacite:lumiere-de-force', 'bestiaire/golem-de-lumiere', 1, NULL, NULL, 'Lumière de force', 'lumiere-de-force', 'Chaque début de tour, cette créature bénéficie d’un champ de force qui encaisse 5 dégâts.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G396:R405');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-lumiere#capacite:phare:npm3', 'bestiaire/golem-de-lumiere', 2, 3, NULL, 'Phare', 'phare', 'Tous les 3 tours, la créature fait exploser une lumière qui inflige 10 dégâts fixe qui perce AP/AM et forcera le jet de vigueur aux ennemis sur le terrain pour ne pas qu’ils prennent “aveuglement 1”', NULL, 'bestiaire', 'Invocation › Appel aux golems › G396:R405');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-magma#capacite:bouclier-de-feu', 'bestiaire/golem-de-magma', 1, NULL, NULL, 'Bouclier de feu', 'bouclier-de-feu', 'Projette des flammes inesquivables qui infligent 2d6 en réponse à toutes agressions au corps à corps.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G222:R231');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-magma#capacite:moteur-a-vapeur:npm5', 'bestiaire/golem-de-magma', 3, 5, NULL, 'Moteur à vapeur', 'moteur-a-vapeur', 'Quand il prend une attaque de l’élément Eau ou Vent, sa vitesse augmente de +2 pendant 2 tours. Si la météo est positive pour le Vent ou l’Eau, sa vitesse de base monte à 4 et il a +3 à l’initiative.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G222:R231');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-magma#capacite:super-explosion:npm3', 'bestiaire/golem-de-magma', 2, 3, NULL, 'Super explosion', 'super-explosion', 'Les projectiles de cette créature touche une zone de 3x3 au lieu de 2x2.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G222:R231');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-pain#capacite:delicieux', 'bestiaire/golem-de-pain', 1, NULL, NULL, 'Délicieux', 'delicieux', 'Cette créature possède une matière qui est comestible et qui redonne autant qu''une petite fiole rouge. Lui retire 25% de santé en faisant ça.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G19:R28');
