INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-petrole#capacite:gluant', 'bestiaire/golem-de-petrole', 1, NULL, NULL, 'Gluant', 'gluant', 'Cette créature est faite dans une matière gélatineuse, ce qui lui permet d’être résistante face au dégâts de frappe. Sa structure lui inflige une faiblesse contre la paralysie.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G106:R115');
