INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-rouage#capacite:annule-12', 'bestiaire/golem-de-rouage', 1, NULL, NULL, 'Annule 12', 'annule-12', 'Si un adversaire fait un jet de dé et que le nombre 12 est présent dans le résultat, le dé est totalement annulé (que ce soit action ou dégâts).', NULL, 'bestiaire', 'Invocation › Appel aux golems › G135:R144');
