INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-rouage#capacite:sulfateuse:npm3', 'bestiaire/golem-de-rouage', 2, 3, NULL, 'Sulfateuse', 'sulfateuse', 'Les arbalètes n’ont plus de recharge longue.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G135:R144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-sable#capacite:appelareno:npm3', 'bestiaire/golem-de-sable', 2, 3, NULL, 'Appelaréno', 'appelareno', 'Invoque automatiquement la tempête de sable dès que le combat commence.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G338:R347');
