INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-sable#capacite:squelettique', 'bestiaire/golem-de-sable', 1, NULL, NULL, 'Squelettique', 'squelettique', 'Rend cette créature immunisée aux attaques d’estoc.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G338:R347');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-verre#capacite:defense-prismatique:npm5', 'bestiaire/golem-de-verre', 3, 5, NULL, 'Défense prismatique', 'defense-prismatique', 'Quand un coup à été encaissé d’un certain élément, sa résistance à ce dernier augmente pendant 1 tour (cumulable).', NULL, 'bestiaire', 'Invocation › Appel aux golems › G309:R318');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/golem-de-verre#capacite:fait-de-verre', 'bestiaire/golem-de-verre', 1, NULL, NULL, 'Fait de verre', 'fait-de-verre', 'Cette créature est résisantante contre le Feu, Terre, Glace, Eau, Vent et Ombre. Possède une immunité contre la Lumière et l''Acide. Mais possède une sensibilité contre les dégâts sonores.', NULL, 'bestiaire', 'Invocation › Appel aux golems › G309:R318');
