INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/solecorche#capacite:force-solaire', 'bestiaire/solecorche', 1, NULL, NULL, 'Force Solaire', 'force-solaire', 'Perd 25% de sa santé à la fin de chacun de ses tours mais a un bonus de 8 à toutes ses attaques (12 si il y a la météo "grand soleil").', NULL, 'bestiaire', 'Invocation › Animation des morts › G367:R376');
