INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/squelette-venin#capacite:attaque-poison', 'bestiaire/squelette-venin', 1, NULL, NULL, 'Attaque Poison', 'attaque-poison', 'L''une des armes de cette créature est capable d''empoisonnement. Oblige un jet de vigueur pour ne pas être empoisonné au stade 1.', NULL, 'bestiaire', 'Invocation › Animation des morts › W164:AH173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/squelette-venin#capacite:lanceur-de-sorts:npm3', 'bestiaire/squelette-venin', 2, 3, NULL, 'Lanceur de sorts', 'lanceur-de-sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Poison de masse.', NULL, 'bestiaire', 'Invocation › Animation des morts › W164:AH173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/squelette-venin#capacite:sournois:npm5', 'bestiaire/squelette-venin', 3, 5, NULL, 'Sournois+', 'sournois', 'Quand l''adversaire n''est pas attentif au personnage, permet d''infliger un bonus de 2d8 dégâts en plus des dégâts de l''arme.', NULL, 'bestiaire', 'Invocation › Animation des morts › W164:AH173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/squelrail#capacite:humidification:npm5', 'bestiaire/squelrail', 3, 5, NULL, 'Humidification', 'humidification', 'Dispose d''une protection qui vont ignorer les 10 premiers dégâts qui vont lui être infligés lors d''un combat.', NULL, 'bestiaire', 'Invocation › Animation des morts › W222:AH231');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/squelrail#capacite:reparation:npm3', 'bestiaire/squelrail', 2, 3, NULL, 'Réparation', 'reparation', 'Cette créature récupère l''intégralité de sa barrière au début de son tour.', NULL, 'bestiaire', 'Invocation › Animation des morts › W222:AH231');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/squelrail#capacite:souffle-elementaire', 'bestiaire/squelrail', 1, NULL, NULL, 'Souffle élémentaire', 'souffle-elementaire', 'Cette créature est capable de cracher un souffle lié à son élément. Ce souffle est capable d''infliger l''altération d''état lié à l''élément à hauteur de 35% de chance de l''infliger. (les joueurs doivent faire les jets en conséquences pour ne pas prendre l''altération d''état)', NULL, 'bestiaire', 'Invocation › Animation des morts › W222:AH231');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/temposs#capacite:arme-distordu', 'bestiaire/temposs', 1, NULL, NULL, 'Arme distordu', 'arme-distordu', 'L''arme à distance de cette créature possède une portée qui couvre l''entièreté du terrain, il doit toujours au moins voir sa cible pour l''attaquer.', NULL, 'bestiaire', 'Invocation › Animation des morts › W106:AH115');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/temposs#capacite:diagonale-incoherente:npm5', 'bestiaire/temposs', 3, 5, NULL, 'Diagonale incohérente', 'diagonale-incoherente', 'Les diagonales compte pour 1 case de déplacement au lieu de 2.', NULL, 'bestiaire', 'Invocation › Animation des morts › W106:AH115');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/temposs#capacite:double-cible:npm3', 'bestiaire/temposs', 2, 3, NULL, 'Double cible', 'double-cible', 'Cette créature peut toucher deux cibles à la fois avec son arme.', NULL, 'bestiaire', 'Invocation › Animation des morts › W106:AH115');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/verros#capacite:dissipation:npm3', 'bestiaire/verros', 2, 3, NULL, 'Dissipation', 'dissipation', 'Une fois tout les 2 tours, il est capable d''utilisé le sort du Vide "Dissipation" sur un adversaire et ceux gratuitement et comme un IC.', NULL, 'bestiaire', 'Invocation › Animation des morts › W135:AH144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/verros#capacite:esprit-vide:npm5', 'bestiaire/verros', 3, 5, NULL, 'Esprit vide', 'esprit-vide', 'Tant que cette créature est sur le terrain, l''invocateur ne peut pas subir d''attaque mental ou de contrôle mental.', NULL, 'bestiaire', 'Invocation › Animation des morts › W135:AH144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/verros#capacite:voit-rouge', 'bestiaire/verros', 1, NULL, NULL, 'Voit rouge', 'voit-rouge', 'Oblige un jet de vigueur ou fermeté à l''adversaire, si raté, ne peut utiliser de magie pendant son tour. (Action)', NULL, 'bestiaire', 'Invocation › Animation des morts › W135:AH144');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombi#capacite:temeraire', 'bestiaire/zombi', 1, NULL, NULL, 'Téméraire', 'temeraire', 'Cette créature est toujours en offensive et ne possède pas le malus pour toucher sa cible.', NULL, 'bestiaire', 'Invocation › Animation des morts › G19:R28');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombi-ronce#capacite:attaque-saignante:npm5', 'bestiaire/zombi-ronce', 3, 5, NULL, 'Attaque saignante', 'attaque-saignante', 'L''attaque de cette créature est capable d''infliger un saignement, oblige un jet de vigueur à la cible pour éviter "saignement 1".', NULL, 'bestiaire', 'Invocation › Animation des morts › G280:R289');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombi-ronce#capacite:lanceur-de-sorts:npm3', 'bestiaire/zombi-ronce', 2, 3, NULL, 'Lanceur de sorts', 'lanceur-de-sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Peau de pierre, Armure de roche, Infection.', NULL, 'bestiaire', 'Invocation › Animation des morts › G280:R289');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombi-ronce#capacite:temeraire', 'bestiaire/zombi-ronce', 1, NULL, NULL, 'Téméraire', 'temeraire', 'Cette créature est toujours en offensive et ne possède pas le malus pour toucher sa cible.', NULL, 'bestiaire', 'Invocation › Animation des morts › G280:R289');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombi-soldat#capacite:attaque-poison:npm3', 'bestiaire/zombi-soldat', 2, 3, NULL, 'Attaque Poison', 'attaque-poison', 'L''une des armes de cette créature est capable d''empoisonnement. Oblige un jet de vigueur pour ne pas être empoisonné au stade 1.', NULL, 'bestiaire', 'Invocation › Animation des morts › G164:R173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombi-soldat#capacite:intervention:npm5', 'bestiaire/zombi-soldat', 3, 5, NULL, 'Intervention', 'intervention', 'Cette créature est capable de prendre un coup à la place d''un allié si il est à côté de lui.', NULL, 'bestiaire', 'Invocation › Animation des morts › G164:R173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombi-soldat#capacite:temeraire', 'bestiaire/zombi-soldat', 1, NULL, NULL, 'Téméraire', 'temeraire', 'Cette créature est toujours en offensive et ne possède pas le malus pour toucher sa cible.', NULL, 'bestiaire', 'Invocation › Animation des morts › G164:R173');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombinox#capacite:crache-chakra:npm3', 'bestiaire/zombinox', 2, 3, NULL, 'Crache chakra', 'crache-chakra', 'Tous les 10% de santé perdu, cette créature libère “Boule de chakra” sur tous les ennemis qui sont à 6 cases de portée sur le terrain, ce sort va infliger 4d6 dégâts magiques.', NULL, 'bestiaire', 'Invocation › Animation des morts › G48:R57');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombinox#capacite:super-sante', 'bestiaire/zombinox', 1, NULL, NULL, 'Super santé', 'super-sante', 'Cette créature possède le double de santé.', NULL, 'bestiaire', 'Invocation › Animation des morts › G48:R57');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombinox#capacite:tu-ne-passe-pas:npm5', 'bestiaire/zombinox', 3, 5, NULL, 'Tu ne passe pas', 'tu-ne-passe-pas', 'Permet de bloquer les adversaires dans sa zone d’influence complète. Permet également d’intercepter les attaques avec un jet de défense réussi.', NULL, 'bestiaire', 'Invocation › Animation des morts › G48:R57');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombre#capacite:attaque-surprise:npm3', 'bestiaire/zombre', 2, 3, NULL, 'Attaque surprise', 'attaque-surprise', 'Cette créature peut faire une attaque discrète sans jet de discrétion la nuit ou lorsque la météo "Brouillard Obscur" est posé.', NULL, 'bestiaire', 'Invocation › Animation des morts › G396:R405');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombre#capacite:lanceur-de-sorts', 'bestiaire/zombre', 1, NULL, NULL, 'Lanceur de sorts', 'lanceur-de-sorts', 'Cette créature peut lancer les sorts, avec les niveaux de maîtrises maximum : Perturbation, Pichenette.', NULL, 'bestiaire', 'Invocation › Animation des morts › G396:R405');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zombre#capacite:sort-supplementaire:npm5', 'bestiaire/zombre', 3, 5, NULL, 'Sort supplémentaire', 'sort-supplementaire', 'Cette créature obtient de nouveaux sorts en plus des autres : Brouillard Obscur, Malédiction, Amplification sombre.', NULL, 'bestiaire', 'Invocation › Animation des morts › G396:R405');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zompi#capacite:crache-spore', 'bestiaire/zompi', 1, NULL, NULL, 'Crache spore', 'crache-spore', 'Crache des spores dans une zone de 2 cases autour qui force un jet de vigueur, si raté impossible de bouger ET de faire l''action en même temps pour le prochain tour.', NULL, 'bestiaire', 'Invocation › Animation des morts › G309:R318');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zompi#capacite:degustation-deau:npm5', 'bestiaire/zompi', 3, 5, NULL, 'Dégustation d’eau', 'degustation-deau', 'Absorbe les dégâts de l’élément eau, ce qui lui donne +5 dégâts à la prochaine attaque en plus de le soigner à hauteur de 5d6.', NULL, 'bestiaire', 'Invocation › Animation des morts › G309:R318');
INSERT INTO creature_capacite (id, creature_id, rang, npm_min, etiquette, nom, nom_cle, texte, donnees, origine, source_ref) VALUES ('bestiaire/zompi#capacite:tete-fongique:npm3', 'bestiaire/zompi', 2, 3, NULL, 'Tête fongique', 'tete-fongique', 'La tête est protégée et n’est plus considérée comme un point faible.', NULL, 'bestiaire', 'Invocation › Animation des morts › G309:R318');
